package com.azoth.territory;
import static org.junit.jupiter.api.Assertions.assertTrue; import java.nio.file.Files;
import java.nio.file.Path; import org.junit.jupiter.api.Test;
class PluginMintWiringTest { @Test void usesGitHubPackagesAndPinnedMintVersion(){String build=read("paper/build.gradle.kts"); String settings=read("settings.gradle.kts"); String props=read("gradle.properties"); assertTrue(settings.contains("maven.pkg.github.com/aincraft-org/mint")); assertTrue(build.contains("mintApiVersion")); assertTrue(props.contains("mintApiVersion=")); } @Test void mintConfigFailsClosedWithoutBinding(){String s=read("paper/src/main/java/com/azoth/territory/AzothTerritoryPlugin.java"); assertTrue(s.contains("Mode.MINT")); assertTrue(s.contains("bindMintClient")); assertTrue(s.contains("MintClientReceiver.class")); assertTrue(s.contains("setAsyncSettlement")); assertTrue(s.contains("getServicesManager().register"));} @Test void guildServicesAcceptTrustedMintRail(){String s=read("paper/src/main/java/org/aincraft/guilds/GuildsServices.java"); assertTrue(s.contains("MintClientLease")); assertTrue(s.contains("withMintLease"));} private static String read(String f){try{return Files.readString(Path.of(System.getProperty("user.dir")).resolve("..", f));}catch(Exception e){throw new AssertionError(e);}}}
